-- The restricted tables of v0.1 (docs/domain.md): money, hidden without rate access (ADR 0005).
-- Generated by drizzle-kit from src/db/schema.ts, then FORCE ROW LEVEL SECURITY added by hand at
-- the end, since Drizzle does not model it (ADR 0004). FrozenRate and FrozenCostConfig arrive with
-- choosing a scenario, in v0.2.
CREATE TYPE "public"."extra_cost_base" AS ENUM('staff_cost', 'revenue');--> statement-breakpoint
CREATE TYPE "public"."extra_cost_kind" AS ENUM('fixed', 'recurring', 'percentage');--> statement-breakpoint
CREATE TABLE "category_rates" (
	"organization_id" uuid NOT NULL,
	"category_id" uuid NOT NULL,
	"gross_annual_salary" numeric(12,2) NOT NULL,
	"social_security_pct" numeric(5,2) NOT NULL,
	"other_yearly_costs" numeric(12,2) NOT NULL,
	"manual_cost_per_hour" numeric(12,2),
	"sell_rate" numeric(12,2) NOT NULL,
	CONSTRAINT "category_rates_pkey" PRIMARY KEY("organization_id","category_id"),
	CONSTRAINT "category_rates_gross_annual_salary_check" CHECK ("gross_annual_salary" >= 0),
	CONSTRAINT "category_rates_social_security_pct_check" CHECK ("social_security_pct" >= 0),
	CONSTRAINT "category_rates_other_yearly_costs_check" CHECK ("other_yearly_costs" >= 0),
	CONSTRAINT "category_rates_manual_cost_per_hour_check" CHECK ("manual_cost_per_hour" >= 0),
	CONSTRAINT "category_rates_sell_rate_check" CHECK ("sell_rate" >= 0)
);
--> statement-breakpoint
ALTER TABLE "category_rates" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "cost_config" (
	"organization_id" uuid PRIMARY KEY NOT NULL,
	"overhead_pct" numeric(5,2) NOT NULL,
	"buffer_pct" numeric(5,2) NOT NULL,
	"target_margin_pct" numeric(5,2) NOT NULL,
	CONSTRAINT "cost_config_overhead_pct_check" CHECK ("overhead_pct" >= 0),
	CONSTRAINT "cost_config_buffer_pct_check" CHECK ("buffer_pct" >= 0)
);
--> statement-breakpoint
ALTER TABLE "cost_config" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "extra_costs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"scenario_id" uuid NOT NULL,
	"label" text,
	"kind" "extra_cost_kind" NOT NULL,
	"amount" numeric(12,2),
	"percentage" numeric(5,2),
	"base" "extra_cost_base",
	"start_date" date,
	"end_date" date,
	CONSTRAINT "extra_costs_organization_id_id_key" UNIQUE("organization_id","id"),
	CONSTRAINT "extra_costs_label_check" CHECK ("label" ~ '\S' and char_length("label") <= 100),
	CONSTRAINT "extra_costs_kind_check" CHECK (case kind
            when 'percentage' then amount is null and percentage is not null and base is not null
            else amount is not null and percentage is null and base is null
          end),
	CONSTRAINT "extra_costs_dates_check" CHECK ((start_date is null) = (end_date is null)
          and (start_date is null or kind = 'recurring')
          and (end_date is null or end_date >= start_date)),
	CONSTRAINT "extra_costs_amount_check" CHECK ("amount" >= 0),
	CONSTRAINT "extra_costs_percentage_check" CHECK ("percentage" >= 0)
);
--> statement-breakpoint
ALTER TABLE "extra_costs" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "project_pricing" (
	"organization_id" uuid NOT NULL,
	"project_id" uuid NOT NULL,
	"price" numeric(12,2),
	"overhead_pct" numeric(5,2),
	"buffer_pct" numeric(5,2),
	CONSTRAINT "project_pricing_pkey" PRIMARY KEY("organization_id","project_id"),
	CONSTRAINT "project_pricing_price_check" CHECK (price > 0),
	CONSTRAINT "project_pricing_overhead_pct_check" CHECK ("overhead_pct" >= 0),
	CONSTRAINT "project_pricing_buffer_pct_check" CHECK ("buffer_pct" >= 0)
);
--> statement-breakpoint
ALTER TABLE "project_pricing" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "category_rates" ADD CONSTRAINT "category_rates_category_fkey" FOREIGN KEY ("organization_id","category_id") REFERENCES "public"."categories"("organization_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "extra_costs" ADD CONSTRAINT "extra_costs_scenario_fkey" FOREIGN KEY ("organization_id","scenario_id") REFERENCES "public"."scenarios"("organization_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
